#!/usr/bin/env bash
# covenant.sh — Claude Code enforcement engine (generated by install.sh, committed to .githooks/)
# Called by pre-commit and pre-push hooks. Never invoke directly in CI.
#
# STACK-SPECIFIC VARIABLES (filled by init — do not edit manually):
# CRITICAL: All commands must use CHANGED_FILES scoping on large repos (>100k LOC).
# Defaults below apply scoping via git diff. At 1M+ LOC, global scans exceed 30s timeout.
TEST_CMD="${TEST_CMD:-}"   # Set by init with scoped test selection
LINT_CMD="${LINT_CMD:-}"   # Set by init with scoped file paths
TYPE_CMD="${TYPE_CMD:-}"   # Set by init with scoped analysis
COVERAGE_CMD="${COVERAGE_CMD:-}"   # Set by init with affected coverage only
COMPLEXITY_CMD="${COMPLEXITY_CMD:-}"   # Set by init with affected functions only
FRONTEND_TEST_CMD="${FRONTEND_TEST_CMD:-}"   # empty = skip
FRONTEND_LINT_CMD="${FRONTEND_LINT_CMD:-}"   # empty = skip
FRONTEND_TYPE_CMD="${FRONTEND_TYPE_CMD:-}"   # empty = skip

# TEST EXECUTION FLAG: Set --run-tests=true to enable. Default = false (skip tests).
# Usage: --run-tests=true git commit -m "message"
# Or:    --run-tests=true git push
RUN_TESTS="${RUN_TESTS:-false}"
# Allow override via commit message: if message contains [run-tests] or [--run-tests=true], enable
if git log -1 --pretty=%B 2>/dev/null | grep -qiE '\[.*run-?tests.*\]|--run-?tests'; then
    RUN_TESTS="true"
fi

set -euo pipefail

# ── Constants ────────────────────────────────────────────────────────────────
COVENANT_STATE=".claude/covenant_state.json"
SESSION_SPEND=".claude/session_spend.tmp"
GIT_CACHE=".claude/git_cache.json"
BASELINE=".claude/baseline.json"
ORG_POLICY="${HOME}/.claude/org_policy.json"

# Color codes ONLY when stderr is a real terminal. In a VS Code / IDE extension
# wrapper (non-TTY), raw ANSI escapes render as garbage and can freeze the editor
# output pane — so emit plain text there. Works seamlessly in CLI, desktop app,
# and IDE extensions alike.
if [ -t 2 ]; then
    RED='\033[0;31m'; YELLOW='\033[1;33m'; GREEN='\033[0;32m'; RESET='\033[0m'
else
    RED=''; YELLOW=''; GREEN=''; RESET=''
fi

# ── Helpers ───────────────────────────────────────────────────────────────────

_json_get() {
    # Usage: _json_get <file> <key>  — naive but dependency-free jq substitute
    python3 -c "
import json, sys
with open('$1') as f:
    d = json.load(f)
keys = '$2'.split('.')
v = d
for k in keys:
    if k == '': break
    v = v.get(k, '')
print(v if v is not None else '')
" 2>/dev/null || echo ""
}

_json_set() {
    # Usage: _json_set <file> <key> <value>
    python3 -c "
import json, sys
with open('$1') as f:
    d = json.load(f)
keys = '$2'.split('.')
obj = d
for k in keys[:-1]:
    obj = obj.setdefault(k, {})
val = '$3'
try:
    obj[keys[-1]] = json.loads(val)
except:
    obj[keys[-1]] = val
with open('$1', 'w') as f:
    json.dump(d, f, indent=2)
" 2>/dev/null
}

_json_append_audit() {
    # Append one entry to token.token_audit_log; prune entries older than 90 days.
    # Guard matches every other COVENANT_STATE-touching function (_receipt_write,
    # _receipt_has_pass) — without it, a missing ledger (accidental deletion,
    # a bad merge, disk issue, or simply testing hook functions in isolation
    # without the full install flow) turned the LAST call in covenant.sh's
    # success path into an unguarded FileNotFoundError. Under `set -e` that
    # silently aborted the whole script right after "receipt written" and
    # before "COVENANT PASS" ever printed — a real commit that passed every
    # actual check still failed, with a raw Python traceback instead of a
    # clear message. Found via a real end-to-end commit test, not by
    # inspection — pinned in tests/covenant/audit_log_resilience.bats.
    [ -f "$COVENANT_STATE" ] || return 0
    python3 -c "
import json, sys
from datetime import datetime, timedelta
with open('$COVENANT_STATE') as f:
    d = json.load(f)
entry = {'timestamp': '$1', 'trigger': '$2', 'spend_at_run': $3, 'outcome': '$4'}
log = d.get('token', {}).get('token_audit_log', [])
log.append(entry)
cutoff = (datetime.utcnow() - timedelta(days=90)).isoformat()
log = [e for e in log if e.get('timestamp','') >= cutoff]
MAX_AUDIT_ENTRIES = 1000
if len(log) > MAX_AUDIT_ENTRIES:
    log = log[-MAX_AUDIT_ENTRIES:]
d.setdefault('token', {})['token_audit_log'] = log
with open('$COVENANT_STATE', 'w') as f:
    json.dump(d, f, indent=2)
" 2>/dev/null
}

_verify_context_anchoring() {
    # Hash-drift detection: if CLAUDE.md changed since the last covenant pass, the
    # agent may be operating on stale architectural context. Warns once per change
    # cycle — auto-updates the stored hash so the warning doesn't repeat every commit.
    [ -f "CLAUDE.md" ] || return 0
    [ -f "$COVENANT_STATE" ] || return 0
    _CA_HASH=$(sha256sum CLAUDE.md 2>/dev/null | awk '{print $1}' || \
               shasum -a 256 CLAUDE.md 2>/dev/null | awk '{print $1}' || echo "")
    [ -z "$_CA_HASH" ] && return 0
    _CA_STORED=$(_json_get "$COVENANT_STATE" "claude_md_hash")
    if [ -z "$_CA_STORED" ] || [ "$_CA_STORED" = "null" ]; then
        _json_set "$COVENANT_STATE" "claude_md_hash" "\"$_CA_HASH\""
        echo "COVENANT: CLAUDE.md anchored (${_CA_HASH:0:12})." >&2
    elif [ "$_CA_STORED" != "$_CA_HASH" ]; then
        echo -e "${YELLOW}⚠ COVENANT: CLAUDE.md changed since last verified pass — re-read it to refresh architectural alignment before proceeding.${RESET}" >&2
        _json_set "$COVENANT_STATE" "claude_md_hash" "\"$_CA_HASH\""
    fi
}

# ── Fingerprint receipt helpers (spec §4.2 — two distinct forms) ──────────────
# COMMIT_TREE_FP keys receipts (pre-commit writes, pre-push verifies).
# Receipts are pruned to the most recent 50 to bound ledger growth.
_receipt_write() {
    # Usage: _receipt_write <tree_hash> <branch>
    [ -f "$COVENANT_STATE" ] || return 0
    [ -n "$1" ] || return 0
    python3 -c "
import json
from datetime import datetime, timezone
with open('$COVENANT_STATE') as f:
    d = json.load(f)
r = d.setdefault('receipts', {})
r['$1'] = {'timestamp': datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ'), 'branch': '$2', 'outcome': 'pass'}
# Bound growth: keep the 50 most recent by timestamp
if len(r) > 50:
    keep = sorted(r.items(), key=lambda kv: kv[1].get('timestamp',''), reverse=True)[:50]
    d['receipts'] = dict(keep)
with open('$COVENANT_STATE', 'w') as f:
    json.dump(d, f, indent=2)
" 2>/dev/null
}

_receipt_has_pass() {
    # Usage: _receipt_has_pass <tree_hash> -> echoes "yes" or "no"
    if [ ! -f "$COVENANT_STATE" ] || [ -z "$1" ]; then echo "no"; return 0; fi
    python3 -c "
import json
try:
    with open('$COVENANT_STATE') as f:
        d = json.load(f)
    r = d.get('receipts', {}).get('$1', {})
    print('yes' if r.get('outcome') == 'pass' else 'no')
except Exception:
    print('no')
" 2>/dev/null || echo "no"
}

_graph_spawn_build() {
    # Usage: _graph_spawn_build <pid_file> — shared by freshness and the
    # watchdog so both spawn identically and clean up their own pid file.
    _GSB_PID_FILE="$1"
    nohup bash -c "code-review-graph build > /dev/null 2>&1; rm -f '$_GSB_PID_FILE'" > /dev/null 2>&1 &
    echo $! > "$_GSB_PID_FILE"
}

_ensure_graph_freshness() {
    # Kill-and-restart lifecycle: always rebuilds for the current HEAD.
    # If a prior build is still running, it is explicitly terminated before
    # a fresh build is spawned, eliminating stale-index drift across commits.
    [ -f ".mcp.json" ] || return 0
    command -v code-review-graph >/dev/null 2>&1 || return 0
    _GF_HIT=$(echo "$CHANGED_FILES" | grep -E '\.(ts|tsx|py|go|java)$' | head -1 || true)
    [ -n "$_GF_HIT" ] || return 0
    _GF_PID_FILE=".claude/graph.pid"
    if [ -f "$_GF_PID_FILE" ]; then
        _GF_PID=$(cat "$_GF_PID_FILE" 2>/dev/null)
        if [ -n "$_GF_PID" ] && kill -0 "$_GF_PID" 2>/dev/null; then
            _GF_CMD=$(ps -p "$_GF_PID" -o command= 2>/dev/null | tr -d '\n' || echo "")
            if echo "$_GF_CMD" | grep -q "code-review-graph"; then
                echo -e "${YELLOW}[GRAPH GUARD] Active indexer obsolete. Terminating stale process and restarting build for current HEAD...${RESET}" >&2
                kill -9 "$_GF_PID" 2>/dev/null || true
            else
                echo -e "${YELLOW}[GRAPH GUARD] PID ${_GF_PID} reused by unrelated process — skipping kill.${RESET}" >&2
                rm -f "$_GF_PID_FILE"
                return 0
            fi
        fi
        rm -f "$_GF_PID_FILE"
    fi
    _graph_spawn_build "$_GF_PID_FILE"
    echo -e "${GREEN}COVENANT: graph index refreshing in background.${RESET}" >&2
    # A fresh build was just spawned for the current HEAD — any earlier crash
    # is moot now, so the watchdog's restart counter no longer applies.
    [ -f "$COVENANT_STATE" ] && _json_set "$COVENANT_STATE" "mcp_graph.restart_count" "0"
}

_ensure_graph_alive() {
    # Watchdog, not freshness: _ensure_graph_freshness only rebuilds when
    # THIS covenant run touches a graph-relevant file (CHANGED_FILES matches its
    # extension filter). If code-review-graph build crashed on an earlier
    # commit that didn't touch such a file, the stale index sits there
    # indefinitely — no future covenant run would ever notice or retrigger it.
    # This closes that gap: it looks for a pid file whose process died
    # WITHOUT the build's own cleanup trap running (a clean exit always
    # removes its own pid file — see _graph_spawn_build), which is the
    # signature of a crash rather than a normal completion, and relaunches.
    #
    # Recovers from crashes; does not prevent them. Never blocks the covenant —
    # if you see multiple restarts logged in one sitting, report it, since
    # that means code-review-graph is crash-looping, not that this watchdog
    # is failing to do its job.
    [ -f ".mcp.json" ] || return 0
    command -v code-review-graph >/dev/null 2>&1 || return 0
    _GA_PID_FILE=".claude/graph.pid"
    [ -f "$_GA_PID_FILE" ] || return 0
    _GA_PID=$(cat "$_GA_PID_FILE" 2>/dev/null)
    if [ -z "$_GA_PID" ]; then
        rm -f "$_GA_PID_FILE"
        return 0
    fi
    if kill -0 "$_GA_PID" 2>/dev/null; then
        # Alive isn't enough on its own — OS PID reuse could mean the real
        # indexer crashed and the OS handed its old PID to something else
        # entirely (the same class of bug _ensure_graph_freshness's kill path
        # already guards against before calling kill -9). Confirm identity
        # before trusting it as "still running".
        _GA_CMD=$(ps -p "$_GA_PID" -o command= 2>/dev/null | tr -d '\n' || echo "")
        if echo "$_GA_CMD" | grep -q "code-review-graph"; then
            return 0
        fi
        echo -e "${YELLOW}[GRAPH GUARD] PID ${_GA_PID} reused by unrelated process — treating as crashed.${RESET}" >&2
    fi

    # Restart-count bookkeeping. This isn't a true session boundary (covenant_state.json
    # persists across commits), so a 24h rolling window is used as a practical stand-in:
    # crash-loop counts reset once a day rather than accumulating forever.
    _GA_COUNT=0
    _GA_MAX=3
    if [ -f "$COVENANT_STATE" ]; then
        _GA_COUNT=$(_json_get "$COVENANT_STATE" "mcp_graph.restart_count")
        _GA_LAST=$(_json_get "$COVENANT_STATE" "mcp_graph.restart_last_ts")
        case "$_GA_COUNT" in ''|*[!0-9]*) _GA_COUNT=0 ;; esac
        if [ -n "$_GA_LAST" ] && [ "$_GA_LAST" != "null" ]; then
            _GA_LAST_EPOCH=$(date -d "$_GA_LAST" +%s 2>/dev/null || date -j -f "%Y-%m-%dT%H:%M:%SZ" "$_GA_LAST" +%s 2>/dev/null || echo "0")
            _GA_NOW_EPOCH=$(date +%s 2>/dev/null || echo "0")
            if [ "${_GA_NOW_EPOCH:-0}" -gt 0 ] && [ "${_GA_LAST_EPOCH:-0}" -gt 0 ] && [ $(( _GA_NOW_EPOCH - _GA_LAST_EPOCH )) -gt 86400 ]; then
                _GA_COUNT=0
            fi
        fi
    fi

    if [ "$_GA_COUNT" -ge "$_GA_MAX" ]; then
        echo -e "${YELLOW}[GRAPH GUARD] code-review-graph has crashed ${_GA_COUNT} times in the last 24h — auto-restart capped at ${_GA_MAX}. Graph-backed review may be stale; investigate and report.${RESET}" >&2
        return 0
    fi

    _GA_COUNT=$((_GA_COUNT + 1))
    if [ -f "$COVENANT_STATE" ]; then
        _json_set "$COVENANT_STATE" "mcp_graph.restart_count" "$_GA_COUNT"
        _json_set "$COVENANT_STATE" "mcp_graph.restart_last_ts" "\"${NOW_ISO:-}\""
    fi
    echo -e "${YELLOW}[GRAPH GUARD] code-review-graph build crashed (pid ${_GA_PID} gone without its normal cleanup) — restarting (attempt ${_GA_COUNT}/${_GA_MAX}).${RESET}" >&2
    rm -f "$_GA_PID_FILE"
    _graph_spawn_build "$_GA_PID_FILE"
}

_is_claude_agent_process() {
    IS_AGENT=false

    # Environment-marker check first. Claude Code sets $CLAUDECODE in every
    # process it spawns, and environment variables are inherited across
    # setsid/nohup/disown/backgrounding — unlike PPID, which changes on
    # reparenting. An agent that backgrounds a commit (`git commit ... &`)
    # and lets its own tool call return before the commit finishes can sever
    # the live process-tree link the walk below depends on: the orphaned
    # child gets reparented (typically to PID 1 or a subreaper) before covenant.sh
    # ever runs, so the walk finds no claude-code ancestor at all. The env
    # marker survives that because it's inherited at fork/exec time from the
    # ORIGINAL environment, not read from the live process table at walk time.
    # Known limitation: an agent that deliberately strips its own environment
    # (`env -u CLAUDECODE ...` or `env -i ...`) before the command defeats
    # this — the same fundamental limit as any client-side self-identification
    # signal (see the Bash-guard hook's lexical-scanning limit, Module A7).
    # This closes the realistic accidental-detachment case, not a deliberate,
    # security-research-level evasion attempt.
    if [ -n "${CLAUDECODE:-}" ]; then
        IS_AGENT=true
        return 0
    fi

    # Fallback: traverse the OS process tree from PPID to PID 1; set
    # IS_AGENT=true if any ancestor binary is the Claude Code CLI. Covers the
    # case where the env marker isn't set (older Claude Code versions, or a
    # host that doesn't set it) but the process tree is still intact.
    CURRENT_PID=$PPID
    while [ "${CURRENT_PID:-0}" -gt 1 ] 2>/dev/null; do
        _AP_CMD=$(ps -p "$CURRENT_PID" -o command= 2>/dev/null | tr -d '\n' || echo "")
        if echo "$_AP_CMD" | grep -qE '@anthropic-ai/claude-code|claude-code'; then
            IS_AGENT=true
            break
        fi
        _AP_PPID=$(ps -p "$CURRENT_PID" -o ppid= 2>/dev/null | tr -d ' \n' || echo "0")
        [ -z "$_AP_PPID" ] || [ "$_AP_PPID" = "0" ] && break
        CURRENT_PID=$_AP_PPID
    done
}

_run_with_timeout() {
    local timeout_sec cmd_label
    timeout_sec=$(_json_get "$COVENANT_STATE" "thresholds.command_timeout_sec")
    timeout_sec="${timeout_sec:-30}"
    cmd_label="$1"; shift
    # Use timeout(1) if available; fall back to plain execution
    if command -v timeout >/dev/null 2>&1; then
        if ! timeout "$timeout_sec" "$@" 2>&1; then
            local exit_code=$?
            if [ $exit_code -eq 124 ]; then
                echo -e "${YELLOW}⚠ TIMEOUT: '$cmd_label' exceeded ${timeout_sec}s — killed and logged${RESET}" >&2
                _json_append_audit "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "timeout" 0 "timeout:${cmd_label}"
                return 1
            fi
            return $exit_code
        fi
    else
        "$@"
    fi
}

# ── CRASH GUARD ───────────────────────────────────────────────────────────────
# Any unhandled non-zero exit from covenant.sh is a BLOCK, never a silent pass.
# stderr is emitted verbatim so the engineer sees the root cause.
_crash_handler() {
    echo -e "${RED}COVENANT CRASH at line $1 — exit $2. Commit blocked. Fix covenant.sh or contact platform team.${RESET}" >&2
    exit 1
}
trap '_crash_handler ${LINENO} $?' ERR

# ── COVENANT_STATE guard ──────────────────────────────────────────────────────────
if [ ! -f "$COVENANT_STATE" ]; then
    echo -e "${YELLOW}⚠ covenant_state.json not found — running cold start (full scan)${RESET}" >&2
fi

# ── CLAUDE.md context anchoring ───────────────────────────────────────────────
_verify_context_anchoring

# ── STEP 1: BRANCH VALIDATION ─────────────────────────────────────────────────
CURRENT_BRANCH=$(git branch --show-current 2>/dev/null || echo "")
# Skip in CI: this guard exists to block a human/agent committing directly
# onto a protected branch checked out locally — a genuinely different thing
# from CI verifying content that already landed on that branch through a
# legitimate path (a merged, reviewed PR). actions/checkout@v4 checks out a
# real local branch (not detached HEAD) for a push event, so on every single
# ci-covenant.yml push-trigger run against main/master/develop/release/
# production — its entire reason for existing, per the workflow's own
# comment: catching a hook-stripped clone or a --no-verify push that landed
# directly on one of these branches — this check fired first and blocked
# unconditionally, before the real mechanical checks (secrets, layer
# boundary, lint, tests) ever ran. That made the push-triggered CI backstop
# permanently red for every legitimate merge and, worse, meaningless as a
# backstop: the exact violation it exists to catch never actually got
# checked. The direct-push case itself is independently and correctly
# blocked at the git level by templates/pre-push's own protected-branch
# guard, which runs before covenant.sh regardless of trigger — this
# CI-mode exemption doesn't reopen that path. Confirmed by directly running
# the real ci-covenant.yml workflow against a real GitHub Actions-equivalent
# runner (act + the catthehacker/ubuntu image, actions/checkout@v4 included),
# not inferred from reading the YAML.
if [ "$COVENANT_TRIGGER" != "ci" ] && [[ "$CURRENT_BRANCH" =~ ^(main|master|develop)$ ]]; then
    echo -e "${RED}BRANCH BLOCK: Direct commits to '$CURRENT_BRANCH' are forbidden.${RESET}" >&2
    echo "Create a feature/bugfix/hotfix/release branch." >&2
    exit 1
fi

BRANCH_PREFIX="${CURRENT_BRANCH%%/*}"
if [[ ! "$BRANCH_PREFIX" =~ ^(feature|bugfix|hotfix|release)$ ]] && [ -n "$CURRENT_BRANCH" ]; then
    echo -e "${YELLOW}⚠ Branch '$CURRENT_BRANCH' does not follow Gitflow naming.${RESET}" >&2
    # Warn only — do not block; human-facing warning is sufficient at covenant level
fi

# Enforce code_writes_permitted from branch_strategy in covenant_state.json.
# release/* branches have code_writes_permitted=false — no new code, diff-review only.
if [ -f "$COVENANT_STATE" ]; then
    _CWP=$(python3 -c "
import json, sys
try:
    with open(sys.argv[1]) as f:
        d = json.load(f)
    s = d.get('branch_strategy', {}).get(sys.argv[2], {})
    print('false' if s.get('code_writes_permitted') is False else 'true')
except Exception:
    print('true')
" "$COVENANT_STATE" "$BRANCH_PREFIX" 2>/dev/null || echo "true")
    if [ "$_CWP" = "false" ]; then
        echo -e "${RED}BRANCH BLOCK: Branch '$CURRENT_BRANCH' (strategy: ${BRANCH_PREFIX}) has code_writes_permitted=false.${RESET}" >&2
        echo "Code writes are not permitted on ${BRANCH_PREFIX} branches. Use a feature or bugfix branch." >&2
        exit 1
    fi
fi

# ── STEP 1.5: S3-BACKED ORG POLICY FETCH (tamper-evident budget) ───────────────
# Fetch the org-wide token budget from S3 with local caching + conservative fallback.
# If S3 is unreachable and no cache exists, default to TOKEN_BUDGET=0 (fail-safe).
_fetch_org_policy_from_s3() {
    local s3_uri="${S3_ORG_POLICY_URI:-s3://company-config/org_policy.json}"
    local cache_file="$ORG_POLICY"
    local cache_ttl_sec=$((24 * 3600))  # 1 day

    # Skip fetch in CI — use committed version only
    if [ "${COVENANT_TRIGGER}" = "ci" ]; then
        return 0
    fi

    # Check if cached version is still fresh
    if [ -f "$cache_file" ]; then
        local now_epoch=$(date +%s)
        local file_mtime=$(stat -f %m "$cache_file" 2>/dev/null || stat -c %Y "$cache_file" 2>/dev/null || echo "0")
        # BSD stat's `-f FORMAT` and GNU stat's `-f` (display FILESYSTEM info,
        # a different flag entirely) collide on some non-macOS/non-Linux `stat`
        # builds (confirmed: Windows git-bash/MSYS) — there, `-f %m` doesn't
        # fail cleanly, it prints multi-line filesystem info to stdout and
        # exits 0, so the `||` fallback never fires and $file_mtime ends up
        # holding that whole blob instead of a timestamp. Validate it's a
        # bare integer before doing arithmetic on it, the same guard style
        # install.sh/uninstall.sh already use for `$behind` — never trust an
        # external command's stdout shape, even from a documented fallback
        # chain, without a numeric sanity check right before `$(( ))`.
        case "$file_mtime" in ''|*[!0-9]*) file_mtime=0 ;; esac
        local file_age=$(( now_epoch - file_mtime ))
        if [ "$file_age" -lt "$cache_ttl_sec" ]; then
            return 0  # Cache is fresh, reuse it
        fi
    fi

    # Attempt to fetch from S3
    if command -v aws >/dev/null 2>&1; then
        if aws s3 cp "$s3_uri" "$cache_file" 2>/dev/null; then
            echo -e "${GREEN}✓ Updated org budget from S3${RESET}" >&2
            return 0
        fi
    fi

    # S3 unreachable — use conservative fallback
    if [ ! -f "$cache_file" ]; then
        echo -e "${YELLOW}⚠ S3 unreachable and no cached org policy — using TOKEN_BUDGET=0 (fail-safe)${RESET}" >&2
        python3 -c "
import json
d = {'TOKEN_BUDGET': 0, 'WEEKLY_LIMIT': 0, 'DAILY_BUDGET_PCT': 0}
with open('$cache_file', 'w') as f:
    json.dump(d, f)
" 2>/dev/null || true
    else
        local cache_mtime=$(stat -f %m "$cache_file" 2>/dev/null || stat -c %Y "$cache_file" 2>/dev/null || echo "0")
        case "$cache_mtime" in ''|*[!0-9]*) cache_mtime=0 ;; esac
        local file_age_hours=$(( ( $(date +%s) - cache_mtime ) / 3600 ))
        echo -e "${YELLOW}⚠ S3 unreachable — using cached budget from ${file_age_hours}h ago${RESET}" >&2
    fi
    return 0
}

# Fetch org policy from S3 (with fallback)
_fetch_org_policy_from_s3

# ── STEP 2: TOKEN HARNESS ─────────────────────────────────────────────────────
TODAY=$(date +%Y-%m-%d)
COVENANT_TRIGGER="${COVENANT_TRIGGER:-pre-commit}"   # pre-commit or pre-push hook sets this
NOW_ISO=$(date -u +%Y-%m-%dT%H:%M:%SZ)

# Read org-level budget ceiling — daily budget = WEEKLY_LIMIT × DAILY_BUDGET_PCT ÷ 100
ORG_BUDGET=""
if [ -f "$ORG_POLICY" ]; then
    ORG_BUDGET=$(python3 -c "
import json, sys
try:
    d = json.load(open('$ORG_POLICY'))
    weekly = int(d.get('WEEKLY_LIMIT') or 0)
    pct    = int(d.get('DAILY_BUDGET_PCT') or 20)
    if weekly > 0:
        print(int(weekly * pct / 100))
    elif d.get('TOKEN_BUDGET'):
        print(int(d['TOKEN_BUDGET']))
except Exception:
    pass
" 2>/dev/null || echo "")
fi

TOKEN_BUDGET=""
if [ -f "$COVENANT_STATE" ]; then
    TOKEN_BUDGET=$(_json_get "$COVENANT_STATE" "token.token_budget")
fi
# Fallback: 200k/day if org policy absent and no repo-level override
[ -z "$TOKEN_BUDGET" ] || [ "$TOKEN_BUDGET" = "null" ] && TOKEN_BUDGET=""
TOKEN_BUDGET="${TOKEN_BUDGET:-200000}"

# Org ceiling wins if set and lower than repo setting
if [ -n "$ORG_BUDGET" ] && [ "$ORG_BUDGET" -lt "$TOKEN_BUDGET" ] 2>/dev/null; then
    TOKEN_BUDGET="$ORG_BUDGET"
fi

# Date-roll reset
if [ -f "$COVENANT_STATE" ]; then
    LAST_RESET=$(_json_get "$COVENANT_STATE" "token.token_last_reset")
    if [ "$LAST_RESET" != "$TODAY" ]; then
        _json_set "$COVENANT_STATE" "token.token_spent_today" "0"
        _json_set "$COVENANT_STATE" "token.token_last_reset" "\"$TODAY\""
    fi
fi

# Accumulate session spend from tmp file
SESSION_SPEND_VAL=0
if [ -f "$SESSION_SPEND" ]; then
    SESSION_SPEND_VAL=$(cat "$SESSION_SPEND" 2>/dev/null | tr -cd '0-9' || echo "0")
    SESSION_SPEND_VAL="${SESSION_SPEND_VAL:-0}"
fi

SPENT_TODAY=0
if [ -f "$COVENANT_STATE" ]; then
    SPENT_TODAY=$(_json_get "$COVENANT_STATE" "token.token_spent_today")
    SPENT_TODAY="${SPENT_TODAY:-0}"
fi
TOTAL_SPENT=$(( SPENT_TODAY + SESSION_SPEND_VAL ))

# Threshold evaluation
OUTCOME="pass"
if [ "$TOKEN_BUDGET" -gt 0 ] 2>/dev/null; then
    PCT=$(( TOTAL_SPENT * 100 / TOKEN_BUDGET ))
    if [ "$PCT" -ge 100 ]; then
        if [ "${SESSION_SPEND_VAL:-0}" -gt 0 ] 2>/dev/null; then
            # Active Claude session is adding new spend right now — block it.
            # Human-authored commits (no live session, SESSION_SPEND_VAL=0) are
            # never blocked here: covenant.sh clears session_spend.tmp after every pass,
            # so a zero value reliably means no agent involvement in this commit.
            echo -e "${RED}TOKEN BUDGET EXHAUSTED — ${TOTAL_SPENT}/${TOKEN_BUDGET} tokens used today.${RESET}" >&2
            echo "This commit comes from an active Claude session (session: +${SESSION_SPEND_VAL} tokens)." >&2
            echo "AI-assisted workflow is paused until tomorrow's daily reset." >&2
            echo "  • Human commits (no active session) pass automatically." >&2
            echo "  • To override right now: SKIP_COVENANT=1 git commit -m \"...\" (prompts for reason + audit note)." >&2
            echo "  • To raise the ceiling: update ~/.claude/org_policy.json TOKEN_BUDGET (human PR required)." >&2
            OUTCOME="hard_block"
            _json_append_audit "$NOW_ISO" "$COVENANT_TRIGGER" "$TOTAL_SPENT" "hard_block"
            [ -f "$COVENANT_STATE" ] && _json_set "$COVENANT_STATE" "token.token_spent_today" "$TOTAL_SPENT"
            exit 1
        else
            # Budget exhausted but no active session — human-authored commit.
            # Warn once per day so it's visible without becoming noise.
            _LAST_WARN=$(_json_get "$COVENANT_STATE" "token.last_budget_warn_date")
            if [ "${_LAST_WARN}" != "$TODAY" ]; then
                echo -e "${YELLOW}⚠ Token budget exhausted (${TOTAL_SPENT}/${TOKEN_BUDGET}). Human commits pass; Claude sessions are paused until tomorrow.${RESET}" >&2
                [ -f "$COVENANT_STATE" ] && _json_set "$COVENANT_STATE" "token.last_budget_warn_date" "\"$TODAY\""
            fi
        fi
    elif [ "$PCT" -ge 80 ]; then
        # Warn once per day — firing on every commit past 80% causes alert fatigue.
        _LAST_WARN=$(_json_get "$COVENANT_STATE" "token.last_budget_warn_date")
        if [ "${_LAST_WARN}" != "$TODAY" ]; then
            echo -e "${YELLOW}⚠ Token budget at ${PCT}% (${TOTAL_SPENT}/${TOKEN_BUDGET} tokens used today).${RESET}" >&2
            [ -f "$COVENANT_STATE" ] && _json_set "$COVENANT_STATE" "token.last_budget_warn_date" "\"$TODAY\""
            OUTCOME="warn"
        fi
    fi
fi

# ── STEP 3: GRAPH STALENESS CHECK ─────────────────────────────────────────────
if [ -f ".mcp.json" ] && [ -f "$COVENANT_STATE" ]; then
    LAST_BUILD=$(_json_get "$COVENANT_STATE" "mcp_graph.last_build_timestamp")
    if [ -n "$LAST_BUILD" ] && [ "$LAST_BUILD" != "null" ]; then
        LAST_BUILD_EPOCH=$(date -d "$LAST_BUILD" +%s 2>/dev/null || date -j -f "%Y-%m-%dT%H:%M:%SZ" "$LAST_BUILD" +%s 2>/dev/null || echo "0")
        # Skip if date parsing failed (LAST_BUILD_EPOCH=0) to avoid permanent false-positives
        # on environments where neither GNU nor BSD date understands the ISO format.
        if [ "${LAST_BUILD_EPOCH:-0}" -gt 0 ] 2>/dev/null; then
            NOW_EPOCH=$(date +%s)
            STALE_THRESHOLD=$(( 7 * 24 * 3600 ))
            if [ $(( NOW_EPOCH - LAST_BUILD_EPOCH )) -gt "$STALE_THRESHOLD" ]; then
                # Warn once per day — the rebuild takes minutes, devs can't action it
                # mid-commit anyway, so repeating on every commit is pure noise.
                _LAST_GRAPH_WARN=$(_json_get "$COVENANT_STATE" "mcp_graph.last_stale_warn_date")
                if [ "${_LAST_GRAPH_WARN}" != "$TODAY" ]; then
                    echo -e "${YELLOW}Note: code graph not rebuilt in >7 days — run when convenient: code-review-graph build${RESET}" >&2
                    [ -f "$COVENANT_STATE" ] && _json_set "$COVENANT_STATE" "mcp_graph.last_stale_warn_date" "\"$TODAY\""
                fi
            fi
        fi
    fi
fi

# ── STEP 4: DETERMINE SCAN SCOPE ──────────────────────────────────────────────
# Incremental scan from last_pass_sha; cold start if null or missing.
# last_pass_sha is keyed by branch to prevent cross-branch diff contamination:
# switching from feature/alpha to feature/beta must not inherit alpha's LAST_SHA.
LAST_SHA=""
_BRANCH_KEY=$(echo "$CURRENT_BRANCH" | tr '.' '_')
if [ -f "$COVENANT_STATE" ]; then
    LAST_SHA=$(_json_get "$COVENANT_STATE" "last_pass_sha.${_BRANCH_KEY}")
fi

HEAD_SHA=$(git rev-parse HEAD 2>/dev/null || echo "INIT")

# CI has no staged files — a checkout puts the working tree at HEAD with
# nothing in the index, so "git diff --cached" (the pre-commit/pre-push
# cold-start path below) is unconditionally empty in CI, regardless of what
# the PR/push actually changed. That made the CI covenant silently pass with
# zero checks run on every cold-start CI invocation (the common case: new
# branch, first-time contributor, squashed/rebased history — anything
# without a matching last_pass_sha). ci-covenant.yml sets CI_BASE_SHA (the PR's
# base sha, or the push's previous HEAD) precisely so this branch can diff
# against the real base instead. Only trusted for COVENANT_TRIGGER=ci — a local
# hook has no such env var and must keep using --cached.
if [ "$COVENANT_TRIGGER" = "ci" ] && [ -n "${CI_BASE_SHA:-}" ] && git cat-file -e "${CI_BASE_SHA}^{commit}" 2>/dev/null; then
    echo "COVENANT: ci mode — diffing against base ${CI_BASE_SHA}" >&2
    CHANGED_FILES=$(git diff --name-only "${CI_BASE_SHA}..HEAD" 2>/dev/null)
    SCAN_MODE="ci-diff"
elif [ -z "$LAST_SHA" ] || [ "$LAST_SHA" = "null" ] || [ "$LAST_SHA" = "" ]; then
    if [ "$COVENANT_TRIGGER" = "ci" ] || [ "$COVENANT_TRIGGER" = "pre-push" ]; then
        # No usable base (e.g. github.event.before is all-zeros for a
        # brand-new branch's first push, or a fresh clone/wiped ledger with
        # no last_pass_sha recorded for this branch) — fail SAFE by scanning
        # every tracked file, not fail-open by silently scanning nothing.
        #
        # pre-push MUST NOT reuse the `git diff --cached` fallback below: by
        # the time pre-push runs, the commit has already landed and the index
        # is clean, so `--cached` is unconditionally empty regardless of what
        # the push actually contains. That emptiness silently set
        # HAS_BACKEND/HAS_FRONTEND to false, which skipped lint/type/
        # complexity/layer-boundary checks entirely on every cold-start push
        # (new branch, fresh clone, or a wiped covenant_state.json ledger) while
        # still printing "COVENANT PASS: all checks clean" — found via a real
        # end-to-end push test, pinned in tests/covenant/pre_push_cold_start_scope.bats.
        echo "COVENANT: ${COVENANT_TRIGGER} cold start with no resolvable base — scanning entire tree" >&2
        CHANGED_FILES=$(git ls-files 2>/dev/null)
    else
        echo "COVENANT: cold start — full scan" >&2
        CHANGED_FILES=$(git diff --cached --name-only 2>/dev/null)
    fi
    SCAN_MODE="cold"
else
    CHANGED_FILES=$(git diff --name-only "${LAST_SHA}..HEAD" 2>/dev/null)
    STAGED_FILES=$(git diff --cached --name-only 2>/dev/null)
    # Union: changed since last pass + currently staged
    CHANGED_FILES=$(echo -e "${CHANGED_FILES}\n${STAGED_FILES}" | sort -u | grep -v '^$')
    SCAN_MODE="incremental"
fi

# Detect tiers from file paths
HAS_BACKEND=false; HAS_FRONTEND=false
while IFS= read -r f; do
    [[ "$f" == backend/* ]] || [[ "$f" == src/* ]] || [[ "$f" == app/* ]] || [[ "$f" == *.py ]] || [[ "$f" == *.java ]] || [[ "$f" == *.go ]] || [[ "$f" == *.rs ]] && HAS_BACKEND=true
    [[ "$f" == frontend/* ]] || [[ "$f" == *.tsx ]] || [[ "$f" == *.ts ]] || [[ "$f" == *.jsx ]] && HAS_FRONTEND=true
done <<< "$CHANGED_FILES"

echo "COVENANT: scope=${SCAN_MODE} | backend=${HAS_BACKEND} | frontend=${HAS_FRONTEND}" >&2

# ── STEP 4.2: SCOPED PATCH CONTENT (for the secrets scan) ────────────────────
# Emits the added-line content the secrets scan (STEP 5) should inspect, for
# whichever base STEP 4 above actually resolved for this trigger/scan mode —
# NOT unconditionally `git diff --cached`, which is empty in every context
# except pre-commit with something staged. Before this existed, the secrets
# scan hardcoded `git diff --cached`, so it silently found nothing in ci-diff
# mode (CI_BASE_SHA resolved, nothing staged in a checkout), in incremental
# pre-push (content is committed, not staged, by the time pre-push runs), and
# in cold-start pre-push/CI with no resolvable base (CHANGED_FILES there is a
# bare `git ls-files` file list, not a diff at all) — meaning the CI backstop
# and a pre-push run with no local receipt could both print "COVENANT PASS"
# on a push that contained an actual hardcoded secret, the exact scenario
# ci-covenant.yml's own header comment says it exists to catch. Confirmed by
# directly running the real ci-covenant.yml workflow (via act +
# actions/checkout@v4 against a real GitHub Actions-equivalent runner) with a
# staged secret in the diff and observing COVENANT PASS before this fix — not
# inferred from reading the code.
_secrets_scan_input() {
    case "$SCAN_MODE" in
        ci-diff)
            git diff --diff-filter=ACMR -p "${CI_BASE_SHA}..HEAD" 2>/dev/null
            ;;
        incremental)
            git diff --diff-filter=ACMR -p "${LAST_SHA}..HEAD" 2>/dev/null
            git diff --cached --diff-filter=ACMR -p 2>/dev/null
            ;;
        cold)
            if [ "$COVENANT_TRIGGER" = "ci" ] || [ "$COVENANT_TRIGGER" = "pre-push" ]; then
                # No diff base at all (new branch's first push, wiped ledger)
                # — CHANGED_FILES is a bare file list (git ls-files), not a
                # diff. Fail safe the same way that list itself does: treat
                # every line of every tracked file as "added" content, in the
                # same `+<content>` shape the grep patterns below already
                # expect, rather than silently having nothing to scan.
                while IFS= read -r _f; do
                    [ -n "$_f" ] && [ -f "$_f" ] && sed 's/^/+/' "$_f" 2>/dev/null
                done <<< "$CHANGED_FILES"
            else
                git diff --cached --diff-filter=ACMR -p 2>/dev/null
            fi
            ;;
    esac
}

# ── STEP 4.3: CORE_FILES RATCHET → TIER-3 DETECTION ──────────────────────────
# If any changed file matches a CORE_FILES glob, escalate to TIER-3:
# full test suite (no changed-file scoping) + mandatory test run even at commit.
CORE_FILES_TOUCHED=false
if [ -f "$COVENANT_STATE" ]; then
    CORE_MATCH=$(python3 -c "
import json, fnmatch
try:
    with open('$COVENANT_STATE') as f:
        d = json.load(f)
    patterns = d.get('core_files', []) or []
    changed = '''$CHANGED_FILES'''.split('\n')
    hit = next((c for c in changed if c and any(fnmatch.fnmatch(c, p) for p in patterns)), '')
    print(hit)
except Exception:
    print('')
" 2>/dev/null || echo "")
    if [ -n "$CORE_MATCH" ]; then
        CORE_FILES_TOUCHED=true
        echo -e "${YELLOW}COVENANT: TIER-3 — CORE_FILES touched ('${CORE_MATCH}'). Full suite + mandatory tests.${RESET}" >&2
    fi
fi

# ── STEP 4.4: TIER 3+ BRAINSTORMING HARD BLOCK ───────────────────────────────
# Process-tree lineage check restricts enforcement to Claude agent sessions only;
# human terminal commits pass through with zero friction.
if [ "$COVENANT_TRIGGER" = "pre-commit" ]; then
    _is_claude_agent_process
    if [ "$IS_AGENT" = "true" ]; then
        _T3_COUNT=$(echo "$CHANGED_FILES" | grep -c . 2>/dev/null || echo "0")
        _T3_CKPT=".claude/checkpoints/LATEST.md"
        if [ "${_T3_COUNT:-0}" -ge 5 ] && [ ! -f "$_T3_CKPT" ]; then
            echo -e "${RED}PRE-COMMIT BLOCK: Tier 3+ change footprint (${_T3_COUNT} files) with no brainstorming checkpoint. Write a design brief to .claude/checkpoints/LATEST.md before committing (rule 2.5.9).${RESET}" >&2
            OUTCOME="block:no-brainstorm-checkpoint"
            _json_append_audit "$NOW_ISO" "$COVENANT_TRIGGER" "$TOTAL_SPENT" "$OUTCOME"
            exit 1
        fi
    fi
fi

# ── STEP 4.5: FINGERPRINT FORMS (spec §4.2 — never conflate) ─────────────────
# WORKING_TREE_FP: working-tree state, keys the in-session ledger skip ONLY.
# COMMIT_TREE_FP : the tree actually being committed/pushed, keys receipts.
WORKING_TREE_FP=""
COMMIT_TREE_FP=""
WORKING_TREE_FP=$( { git rev-parse 'HEAD^{tree}' 2>/dev/null; git diff -p 2>/dev/null; git diff --cached -p 2>/dev/null; } | shasum 2>/dev/null | awk '{print $1}' || echo "")

if [ "$COVENANT_TRIGGER" = "pre-push" ]; then
    COMMIT_TREE_FP=$(git rev-parse 'HEAD^{tree}' 2>/dev/null || echo "")
    # Receipt fast-path: a prior pre-commit run already verified this exact tree.
    if [ "$(_receipt_has_pass "$COMMIT_TREE_FP")" = "yes" ]; then
        echo -e "${GREEN}COVENANT: pre-push receipt verified for tree ${COMMIT_TREE_FP:0:12} — checks already passed at commit.${RESET}" >&2
        _json_append_audit "$NOW_ISO" "$COVENANT_TRIGGER" "$TOTAL_SPENT" "pass:receipt"
        exit 0
    fi
    # No receipt → run full mechanical verification now (tests forced on).
    echo -e "${YELLOW}COVENANT: no pre-commit receipt for this tree — running full mechanical checks before push.${RESET}" >&2
    RUN_TESTS="true"
else
    COMMIT_TREE_FP=$(git write-tree 2>/dev/null || echo "")
    # Unstaged-changes visibility warning: the covenant checks the index only.
    # Any tracked file modified in the working tree but not staged is invisible
    # to COMMIT_TREE_FP and will not be inspected in this run. Surface them so
    # the developer is aware before a blind amend or git commit -a could sneak
    # them through (the only true bypass requires --no-verify at both boundaries).
    _UNSTAGED=$(git diff --name-only 2>/dev/null | grep -v '^$' || true)
    if [ -n "$_UNSTAGED" ]; then
        echo -e "${YELLOW}⚠  COVENANT WARN: Tracked files with unstaged changes — NOT checked in this commit:${RESET}" >&2
        echo "$_UNSTAGED" | sed 's/^/     /' >&2
        echo -e "${YELLOW}   Amending with -a or adding these files before push will trigger a full covenant re-run.${RESET}" >&2
    fi
fi

# ── STEP 4.6: PRE-PUSH CHECKPOINT COVENANT ───────────────────────────────────────
# Process-tree lineage check restricts enforcement to Claude agent pushes only;
# human pushes bypass this covenant entirely to preserve zero-friction velocity.
if [ "$COVENANT_TRIGGER" = "pre-push" ]; then
    _is_claude_agent_process
    if [ "$IS_AGENT" = "true" ]; then
        _CKPT=".claude/checkpoints/LATEST.md"
        _PP_SRC=$(echo "$CHANGED_FILES" | grep -E '\.(ts|tsx|py|go|java|rb|rs|c|cpp|h|cs|swift|kt)$' | head -1 || true)
        if [ -n "$_PP_SRC" ]; then
            if [ ! -f "$_CKPT" ]; then
                echo -e "${RED}PUSH GATING FAILURE: Agent push modifies source files without a checkpoint. Write a summary to .claude/checkpoints/LATEST.md before crossing the remote push boundary.${RESET}" >&2
                echo "Write a checkpoint summarising what changed, why, and the architectural delta against baseline." >&2
                OUTCOME="block:no-checkpoint"
                _json_append_audit "$NOW_ISO" "$COVENANT_TRIGGER" "$TOTAL_SPENT" "$OUTCOME"
                exit 1
            fi
            _CKPT_LAST_COMMIT=$(git log -1 --format=%ct 2>/dev/null || echo "0")
            _CKPT_MTIME=$(stat -f %m "$_CKPT" 2>/dev/null || stat -c %Y "$_CKPT" 2>/dev/null || echo "0")
            case "$_CKPT_MTIME" in ''|*[!0-9]*) _CKPT_MTIME=0 ;; esac
            if [ "${_CKPT_MTIME:-0}" -lt "${_CKPT_LAST_COMMIT:-1}" ] 2>/dev/null; then
                echo -e "${YELLOW}⚠ COVENANT: checkpoint predates the latest commit — update .claude/checkpoints/LATEST.md to reflect current changes before pushing.${RESET}" >&2
            else
                echo "COVENANT: checkpoint verified." >&2
            fi
        fi
    fi
fi

# Mechanical test enforcement: push and CI always run tests; CORE_FILES always run tests.
if [ "$COVENANT_TRIGGER" = "pre-push" ] || [ "$COVENANT_TRIGGER" = "ci" ] || [ "$CORE_FILES_TOUCHED" = true ]; then
    RUN_TESTS="true"
fi

# ── STEP 5: SECRETS SCAN ─────────────────────────────────────────────────────
# Keyword patterns catch a secret when an English identifier (password,
# secret, token, api_key...) sits near the value. They do NOT catch a bare
# credential with no such identifier nearby. The format patterns below
# (AKIA.../ghp_.../xox[baprs]-.../sk_live_.../pk_live_...) close that specific
# gap for well-known, high-confidence credential prefixes — the same class of
# signature git-secrets/gitleaks/trufflehog use, not a general entropy
# scanner. A secret with no recognizable keyword AND no recognizable prefix
# (e.g. a bare opaque token from an unlisted vendor) still is not caught; that
# requires content-decoding/entropy analysis, out of scope for a keyword+
# format scanner by design (see docs/SECURITY_POSTURE.md).
# The PEM-header pattern below (replacing the old algorithm-specific-only
# version) catches the modern, algorithm-less PKCS8 private-key header format
# that the old pattern missed, along with every prefixed variant
# (RSA/EC/OPENSSH/DSA/ENCRYPTED/PGP) it already caught. (Its exact literal
# form is deliberately not spelled out in this comment: the previous wording
# quoted it directly as an example, which — being this framework's own
# source file, committed as .githooks/covenant.sh on every fresh install —
# then matched the very pattern it was documenting, false-positive-blocking
# every fresh install's own governance commit. See tests/covenant/secrets_block.bats
# for the executable specification instead.)
# The keyword group now requires an assignment-like delimiter directly glued
# to the word (colon or equals, optionally through one closing quote) before
# it counts as a match, instead of matching the bare word anywhere in a line.
# Without that requirement, ordinary prose discussing token budgeting (real
# phrasing used throughout this framework's own v1_release dev-guide content)
# and this framework's own covenant_state.json template (a top-level schema
# section literally named after one of these keywords, holding an object, not
# a credential) false-positive-blocked the very first commit of a fresh
# install: confirmed by direct reproduction, and independently flagged (but
# never fixed here) in CovenantWin's covenantwin.py source comments, which
# dropped the bare keywords entirely for the same reason. Format-based
# prefixes (AKIA.../ghp_.../sk_live_...) are unaffected — they were never
# bare-keyword matches and stay high-confidence on their own. (Deliberately
# not spelling out the exact glued-delimiter shape here in inline examples:
# doing so the first time round produced example syntax that matched this
# very regex once this comment itself became part of a staged diff — see
# tests/covenant/secrets_block.bats for the precise, executable specification
# instead of prose that can drift from the real pattern or re-trigger it.)
SECRETS_FOUND=0
if _secrets_scan_input | \
    grep -iE '((api[_-]?key|secret|password|token|private[_-]?key|aws_access)"?[[:space:]]*[:=]|BEGIN [A-Z ]*PRIVATE KEY|AKIA[0-9A-Z]{16}|gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,}|xox[baprs]-[A-Za-z0-9-]{10,}|sk_live_[A-Za-z0-9]{20,}|pk_live_[A-Za-z0-9]{20,})' 2>/dev/null | \
    grep -v '^---\|^+++\|^@@\|^#\|placeholder\|example\|REDACTED\|[:=][[:space:]]*[{[][[:space:]]*$' 2>/dev/null | \
    grep -q .; then
    SECRETS_FOUND=1
fi
if [ "$SECRETS_FOUND" -eq 1 ]; then
    echo -e "${RED}COVENANT BLOCK: Potential secret detected in diff. Review staged changes.${RESET}" >&2
    OUTCOME="block:secrets"
    _json_append_audit "$NOW_ISO" "$COVENANT_TRIGGER" "$TOTAL_SPENT" "$OUTCOME"
    exit 1
fi

# ── STEP 5.5: SCOPED COMMAND INJECTION ──────────────────────────────────────
# CRITICAL FOR 100k+ LOC: Scope all linters, type-checkers, and tests to changed
# files only. Global scans exceed 30s timeout on large repos. The init process
# fills these variables with stack-specific scoped commands using CHANGED_FILES.
# If init leaves them empty, covenant.sh derives scoped versions automatically here.

# ── Dynamic Stack Inference (§6.0) ───────────────────────────────────────────
# Infer test runners from repo topology — never default to a static pytest command.

# Candidate subdirectories checked in addition to the repo root. A repo with
# a backend/ + frontend/ split (the common brownfield monorepo layout — e.g.
# backend/requirements.txt, frontend/package.json, nothing at root) otherwise
# matched none of the root-only manifest checks below, so TEST_RUNNERS stayed
# empty and every commit hit "no test runner found" until a human manually
# exported TEST_CMD/FRONTEND_TEST_CMD — despite the layout being extremely
# common, not an edge case. Found via a real end-to-end install against such
# a repo, pinned in tests/covenant/monorepo_subdir_inference.bats.
#
# TEST_CMD_SUBDIRS covers _infer_backend_test_cmd, which (despite the name —
# it predates the frontend/ split, and also covers generic jest/vitest/
# npm-test detection) must search frontend subdirs too: a repo's
# package.json with a "test" script commonly lives under frontend/
# (jest/vitest unit tests), separate from playwright e2e config.
# FRONTEND_SUBDIRS alone is used for playwright e2e config discovery
# (_infer_playwright_cmd) — e2e specs conventionally live in the frontend
# app directory, not backend/server/api.
TEST_CMD_SUBDIRS=". backend server api frontend web client ui"
FRONTEND_SUBDIRS=". frontend web client ui"

_has_playwright_config_in_dir() {
    local dir="$1"
    [ -f "${dir}/playwright.config.ts" ] || [ -f "${dir}/playwright.config.js" ] || \
    [ -f "${dir}/playwright.config.mjs" ] || \
    { [ -f "${dir}/package.json" ] && grep -q '@playwright/test' "${dir}/package.json" 2>/dev/null; }
}

_has_playwright_config() {
    local d
    for d in $FRONTEND_SUBDIRS; do
        _has_playwright_config_in_dir "$d" && return 0
    done
    return 1
}

# Usage: _scope_to_dir <changed_files> <dir> — files under $dir with the
# prefix stripped (so they're valid relative paths once the runner itself
# `cd`s into $dir); ".": passthrough unchanged.
_scope_to_dir() {
    local changed="$1" dir="$2"
    if [ "$dir" = "." ]; then
        echo "$changed"
    else
        echo "$changed" | grep -E "^${dir}/" | sed "s|^${dir}/||"
    fi
}

# Usage: _wrap_in_dir <cmd> <dir> — a root-relative command runs as-is; a
# subdirectory command is wrapped in a subshell `cd` so its own relative
# file arguments (already stripped by _scope_to_dir) resolve correctly.
_wrap_in_dir() {
    local cmd="$1" dir="$2"
    if [ "$dir" = "." ]; then
        echo "$cmd"
    else
        echo "(cd '${dir}' && ${cmd})"
    fi
}

# Usage: _dirjoin <dir> <name> — "." + "x" -> "x" (not "./x"); "backend" + "x"
# -> "backend/x". A plain top-level helper (not a per-call closure) so it
# doesn't redefine a global function named after a single generic letter on
# every invocation of the callers below.
_dirjoin() {
    if [ "$1" = "." ]; then
        echo "$2"
    else
        echo "$1/$2"
    fi
}

_infer_backend_test_cmd_in_dir() {
    local changed="$1" dir="$2"
    local py_changed go_changed js_changed

    # Python: pytest via config manifests
    if [ -f "$(_dirjoin "$dir" pytest.ini)" ] || [ -f "$(_dirjoin "$dir" conftest.py)" ] || \
       { [ -f "$(_dirjoin "$dir" pyproject.toml)" ] && grep -q '\[tool\.pytest' "$(_dirjoin "$dir" pyproject.toml)" 2>/dev/null; } || \
       { [ -f "$(_dirjoin "$dir" setup.cfg)" ] && grep -q '\[tool:pytest\]' "$(_dirjoin "$dir" setup.cfg)" 2>/dev/null; } || \
       { ls "$(_dirjoin "$dir" requirements)"*.txt >/dev/null 2>&1 && grep -qE '^pytest' "$(_dirjoin "$dir" requirements)"*.txt 2>/dev/null; }; then
        py_changed=$(_scope_to_dir "$changed" "$dir" | grep -E '\.py$' | tr '\n' ' ' || true)
        if [ -n "$py_changed" ]; then
            _wrap_in_dir "pytest -x -q --tb=short ${py_changed} 2>&1 | head -100" "$dir"
        else
            _wrap_in_dir "pytest -x -q --tb=short 2>&1 | head -100" "$dir"
        fi
        return 0
    fi

    # Node/JS: jest, vitest, or npm test script
    if [ -f "$(_dirjoin "$dir" package.json)" ]; then
        js_changed=$(_scope_to_dir "$changed" "$dir" | grep -E '\.(ts|tsx|js|jsx)$' | tr '\n' ' ' || true)
        if grep -q '"jest"' "$(_dirjoin "$dir" package.json)" 2>/dev/null || \
           grep -qE '"test".*jest' "$(_dirjoin "$dir" package.json)" 2>/dev/null; then
            if [ -n "$js_changed" ]; then
                _wrap_in_dir "npm test -- --passWithNoTests --findRelatedTests ${js_changed} 2>&1 | head -100" "$dir"
            else
                _wrap_in_dir "npm test -- --passWithNoTests 2>&1 | head -100" "$dir"
            fi
            return 0
        elif grep -q 'vitest' "$(_dirjoin "$dir" package.json)" 2>/dev/null; then
            _wrap_in_dir "npx vitest run --passWithNoTests 2>&1 | head -100" "$dir"
            return 0
        elif grep -q '"test"' "$(_dirjoin "$dir" package.json)" 2>/dev/null; then
            _wrap_in_dir "npm test 2>&1 | head -100" "$dir"
            return 0
        fi
    fi

    # Go
    if [ -f "$(_dirjoin "$dir" go.mod)" ]; then
        go_changed=$(_scope_to_dir "$changed" "$dir" | grep -E '\.go$' | while read -r f; do dirname "$f"; done 2>/dev/null | sort -u | sed 's|^|./|' | tr '\n' ' ' || true)
        if [ -n "$go_changed" ]; then
            _wrap_in_dir "go test ${go_changed} -count=1 2>&1 | head -100" "$dir"
        else
            _wrap_in_dir "go test ./... -count=1 2>&1 | head -100" "$dir"
        fi
        return 0
    fi

    # Rust
    if [ -f "$(_dirjoin "$dir" Cargo.toml)" ]; then
        _wrap_in_dir "cargo test --quiet 2>&1 | head -100" "$dir"
        return 0
    fi

    # Java/Kotlin — Maven or Gradle
    if [ -f "$(_dirjoin "$dir" pom.xml)" ]; then
        _wrap_in_dir "mvn -q test 2>&1 | head -100" "$dir"
        return 0
    fi
    if [ -f "$(_dirjoin "$dir" build.gradle)" ] || [ -f "$(_dirjoin "$dir" build.gradle.kts)" ]; then
        _wrap_in_dir "./gradlew test --quiet 2>&1 | head -100" "$dir"
        return 0
    fi

    echo ""
}

_infer_backend_test_cmd() {
    local changed="$1" dir cmd
    for dir in $TEST_CMD_SUBDIRS; do
        cmd=$(_infer_backend_test_cmd_in_dir "$changed" "$dir")
        if [ -n "$cmd" ]; then
            echo "$cmd"
            return 0
        fi
    done
    echo ""
}

_infer_playwright_cmd_in_dir() {
    local changed="$1" dir="$2"
    if ! _has_playwright_config_in_dir "$dir"; then
        echo ""
        return 0
    fi
    local scoped pw_specs ui_touched
    scoped=$(_scope_to_dir "$changed" "$dir")
    pw_specs=$(echo "$scoped" | grep -E '\.(spec|e2e)\.(ts|js|mjs)$|/e2e/' | tr '\n' ' ' || true)
    if [ -n "$pw_specs" ]; then
        _wrap_in_dir "npx playwright test ${pw_specs} 2>&1 | head -100" "$dir"
    else
        ui_touched=$(echo "$scoped" | grep -E '(routes/|pages/|components/|frontend/|presentation/|\.tsx$|\.jsx$|nginx\.conf|proxy)' || true)
        if [ -n "$ui_touched" ] || { [ "$dir" != "." ] && [ -n "$scoped" ]; } || { [ "$dir" = "." ] && [ -n "$changed" ]; }; then
            _wrap_in_dir "npx playwright test 2>&1 | head -100" "$dir"
        fi
    fi
}

_infer_playwright_cmd() {
    local changed="$1" dir cmd
    for dir in $FRONTEND_SUBDIRS; do
        cmd=$(_infer_playwright_cmd_in_dir "$changed" "$dir")
        if [ -n "$cmd" ]; then
            echo "$cmd"
            return 0
        fi
    done
    echo ""
}

# Build execution queue: init overrides first, then inferred runners.
# TIER-3 (CORE_FILES touched) runs the FULL suite — pass empty scope so inference
# does not narrow to changed files.
if [ "$CORE_FILES_TOUCHED" = true ]; then
    TEST_SCOPE_FILES=""
else
    TEST_SCOPE_FILES="$CHANGED_FILES"
fi

TEST_RUNNERS=()
if [ -n "$TEST_CMD" ]; then
    TEST_RUNNERS+=("$TEST_CMD")
else
    _INFERRED_BACKEND=$(_infer_backend_test_cmd "$TEST_SCOPE_FILES")
    [ -n "$_INFERRED_BACKEND" ] && TEST_RUNNERS+=("$_INFERRED_BACKEND")
fi

if [ -n "$FRONTEND_TEST_CMD" ]; then
    TEST_RUNNERS+=("$FRONTEND_TEST_CMD")
else
    _INFERRED_PW=$(_infer_playwright_cmd "$TEST_SCOPE_FILES")
    [ -n "$_INFERRED_PW" ] && TEST_RUNNERS+=("$_INFERRED_PW")
fi

if [ ${#TEST_RUNNERS[@]} -gt 0 ]; then
    echo "COVENANT: inferred test runners (${#TEST_RUNNERS[@]}): ${TEST_RUNNERS[*]}" >&2
fi

# Fail closed, not silently, when source was changed but no test command was
# found — neither explicit (TEST_CMD/FRONTEND_TEST_CMD) nor inferred. Scoped
# to $HAS_BACKEND/$HAS_FRONTEND (same classification every other check below
# already uses) so docs-only/config-only commits with no source changes are
# never blocked — only a genuinely untested source change is.
if ( $HAS_BACKEND || $HAS_FRONTEND ) && [ ${#TEST_RUNNERS[@]} -eq 0 ]; then
    echo -e "${RED}PRE-COMMIT BLOCK: source files changed but no test runner was found (neither TEST_CMD/FRONTEND_TEST_CMD nor auto-inference matched).${RESET}" >&2
    echo "Fix: configure TEST_CMD (or FRONTEND_TEST_CMD) in .claude/covenant_state.json for this stack, or this commit cannot pass." >&2
    exit 1
fi

if [ -z "$LINT_CMD" ]; then
    # Scope linting to changed files
    LINT_CHANGED=$(echo "$CHANGED_FILES" | grep -E '\.(py)$' | tr '\n' ' ' || true)
    if [ -n "$LINT_CHANGED" ]; then
        LINT_CMD="ruff check $LINT_CHANGED"
    fi
fi

if [ -z "$TYPE_CMD" ]; then
    # Scope type-checking to changed files
    TYPE_CHANGED=$(echo "$CHANGED_FILES" | grep -E '\.(py)$' | tr '\n' ' ' || true)
    if [ -n "$TYPE_CHANGED" ]; then
        TYPE_CMD="mypy $TYPE_CHANGED --no-error-summary 2>&1 | head -50"
    fi
fi

if [ -z "$COMPLEXITY_CMD" ]; then
    # Scope complexity analysis to changed files only
    COMPLEXITY_CHANGED=$(echo "$CHANGED_FILES" | grep -E '\.(py)$' | tr '\n' ' ' || true)
    if [ -n "$COMPLEXITY_CHANGED" ]; then
        COMPLEXITY_CMD="radon cc -n C $COMPLEXITY_CHANGED"
    fi
fi

# ── STEP 6: BACKEND CHECKS ───────────────────────────────────────────────────
COVERAGE_THRESHOLD=$(_json_get "$COVENANT_STATE" "thresholds.coverage_pct")
COVERAGE_THRESHOLD="${COVERAGE_THRESHOLD:-80}"
COMPLEXITY_THRESHOLD=$(_json_get "$COVENANT_STATE" "thresholds.complexity_max")
COMPLEXITY_THRESHOLD="${COMPLEXITY_THRESHOLD:-10}"

if $HAS_BACKEND && [ -n "$LINT_CMD" ]; then
    echo "COVENANT: running lint..." >&2
    LINT_RC=0
    LINT_OUTPUT=$(bash -c "$LINT_CMD" 2>&1) || LINT_RC=$?

    # Identity-based debt ratchet (brownfield): when a populated baseline.json
    # exists, grandfather pre-existing findings and block only NEW identities.
    # Identity = "<normalized_path>|<rule_code>" (line excluded → format-insensitive).
    # Greenfield (no baseline) keeps zero-tolerance: any lint failure blocks.
    RATCHET_ACTIVE=false
    if [ -f "$BASELINE" ]; then
        RATCHET_ACTIVE=$(python3 -c "
import json
try:
    with open('$BASELINE') as f: b = json.load(f)
    print('true' if b.get('populated') and isinstance(b.get('lint_findings'), list) else 'false')
except Exception:
    print('false')
" 2>/dev/null || echo "false")
    fi

    if [ "$RATCHET_ACTIVE" = "true" ]; then
        NEW_FINDINGS=$(python3 -c "
import json, re, sys
with open('$BASELINE') as f: b = json.load(f)
baseline = set(b.get('lint_findings', []))
new = []
for line in '''$LINT_OUTPUT'''.splitlines():
    m = re.match(r'^([^:]+):\d+:\d+:\s+([A-Z]+[0-9]+)', line.strip())
    if not m:
        continue
    ident = m.group(1) + '|' + m.group(2)
    if ident not in baseline:
        new.append(ident)
for n in sorted(set(new)):
    print(n)
" 2>/dev/null || echo "__PARSE_FAIL__")
        if [ "$NEW_FINDINGS" = "__PARSE_FAIL__" ]; then
            # Unparseable linter format → fall back to exit-code enforcement.
            if [ "$LINT_RC" -ne 0 ]; then
                echo -e "${RED}COVENANT BLOCK: lint failed (ratchet unavailable for this linter format).${RESET}" >&2
                echo "$LINT_OUTPUT" | head -50 >&2
                OUTCOME="block:lint"; _json_append_audit "$NOW_ISO" "$COVENANT_TRIGGER" "$TOTAL_SPENT" "$OUTCOME"; exit 1
            fi
        elif [ -n "$NEW_FINDINGS" ]; then
            echo -e "${RED}COVENANT BLOCK: new lint findings not in baseline (debt ratchet):${RESET}" >&2
            echo "$NEW_FINDINGS" | head -50 >&2
            OUTCOME="block:lint-ratchet"; _json_append_audit "$NOW_ISO" "$COVENANT_TRIGGER" "$TOTAL_SPENT" "$OUTCOME"; exit 1
        else
            echo "COVENANT: lint clean against baseline (pre-existing debt grandfathered)." >&2
        fi
    else
        # No baseline → zero tolerance.
        if [ "$LINT_RC" -ne 0 ]; then
            echo -e "${RED}COVENANT BLOCK: lint failed.${RESET}" >&2
            echo "$LINT_OUTPUT" | head -50 >&2
            OUTCOME="block:lint"; _json_append_audit "$NOW_ISO" "$COVENANT_TRIGGER" "$TOTAL_SPENT" "$OUTCOME"; exit 1
        fi
    fi
fi

if $HAS_BACKEND && [ -n "$TYPE_CMD" ]; then
    echo "COVENANT: running type check..." >&2
    if ! _run_with_timeout "type-check" bash -c "$TYPE_CMD"; then
        echo -e "${RED}COVENANT BLOCK: type check failed.${RESET}" >&2
        OUTCOME="block:type"
        _json_append_audit "$NOW_ISO" "$COVENANT_TRIGGER" "$TOTAL_SPENT" "$OUTCOME"
        exit 1
    fi
fi

# ── STEP 6.5: LAYER BOUNDARY SCAN ────────────────────────────────────────────
# Heuristic grep scan scoped to CHANGED_FILES only (never full-repo).
# Catches the three most common AI-generated layer violations:
#   1. SQL in presentation/routes layer (belongs only in repositories/)
#   2. HTTP framework imports in application/services layer (belongs only in routes/)
#   3. ORM/framework/infrastructure imports in the domain/entities layer (belongs
#      only in infrastructure/) — the domain layer is supposed to be pure
#      business logic with zero external dependencies (Clean Architecture's
#      innermost ring). A prior version of this scan only checked cross-layer
#      SQL/HTTP leakage and had no notion of "any framework" at all, so a
#      domain entity directly importing sqlalchemy committed cleanly even
#      though CLAUDE.md is explicit that this is exactly the violation the
#      four-layer scaffold exists to prevent — found via a real end-to-end
#      commit test, pinned in tests/covenant/layer_boundary_domain_purity.bats.
# Fires only if changed files land in known layer directories — stack-agnostic.
if $HAS_BACKEND && [ -n "$CHANGED_FILES" ]; then
    LAYER_VIOLATIONS=""
    while IFS= read -r _lf; do
        [ -z "$_lf" ] || [ ! -f "$_lf" ] && continue

        # Routes / controllers / presentation layer: must contain NO raw SQL
        if echo "$_lf" | grep -qiE '/(routes?|controllers?|presentation|views?|handlers?)/'; then
            # Python: psycopg2 / raw SQL keywords
            _SQL=$(grep -nE '(SELECT|INSERT|UPDATE|DELETE|cursor\.execute|executemany|psycopg2\.connect)' "$_lf" 2>/dev/null | grep -v '^\s*#\|placeholder\|example' | head -3 || true)
            # Java/Spring: JdbcTemplate, EntityManager, native queries in controllers
            _SQL_JAVA=$(grep -nE '(JdbcTemplate|jdbcTemplate|entityManager\.createNativeQuery|@Query.*nativeQuery\s*=\s*true|\.prepareStatement\()' "$_lf" 2>/dev/null | grep -v '^\s*//' | head -3 || true)
            _SQL="${_SQL}${_SQL_JAVA}"
            if [ -n "$_SQL" ]; then
                LAYER_VIOLATIONS="${LAYER_VIOLATIONS}ROUTES_HAS_SQL ${_lf}:\n${_SQL}\n"
            fi
        fi

        # Services / application layer: must contain NO raw SQL
        if echo "$_lf" | grep -qiE '/(services?|application|use.?cases?)/'; then
            # Python: psycopg2 / raw SQL keywords
            _SQL=$(grep -nE '(SELECT|INSERT|UPDATE|DELETE|cursor\.execute|executemany|psycopg2\.connect)' "$_lf" 2>/dev/null | grep -v '^\s*#\|placeholder\|example' | head -3 || true)
            # Java/Spring: JdbcTemplate, EntityManager, native queries in services
            _SQL_JAVA=$(grep -nE '(JdbcTemplate|jdbcTemplate|entityManager\.createNativeQuery|@Query.*nativeQuery\s*=\s*true|\.prepareStatement\()' "$_lf" 2>/dev/null | grep -v '^\s*//' | head -3 || true)
            _SQL="${_SQL}${_SQL_JAVA}"
            if [ -n "$_SQL" ]; then
                LAYER_VIOLATIONS="${LAYER_VIOLATIONS}SERVICE_HAS_SQL ${_lf}:\n${_SQL}\n"
            fi
        fi

        # Services / application layer: must NOT import HTTP framework directly
        if echo "$_lf" | grep -qiE '/(services?|application|use.?cases?)/'; then
            # Python: FastAPI / Flask / Django HTTP imports
            _HTTP=$(grep -nE '^(from fastapi|import fastapi|from flask|import flask|from django\.http|APIRouter|@app\.(get|post|put|delete|patch)\()' "$_lf" 2>/dev/null | head -3 || true)
            # Java/Spring: controller annotations or servlet types leaked into service layer
            _HTTP_JAVA=$(grep -nE '(@RestController|@Controller|@RequestMapping|HttpServletRequest|HttpServletResponse|ResponseEntity|@GetMapping|@PostMapping|@PutMapping|@DeleteMapping)' "$_lf" 2>/dev/null | grep -v '^\s*//' | head -3 || true)
            _HTTP="${_HTTP}${_HTTP_JAVA}"
            if [ -n "$_HTTP" ]; then
                LAYER_VIOLATIONS="${LAYER_VIOLATIONS}SERVICE_HAS_HTTP ${_lf}:\n${_HTTP}\n"
            fi
        fi

        # Domain / entities layer: must import NOTHING from an ORM, HTTP
        # framework, or infrastructure/driver package — pure business logic
        # only. Deliberately excludes bare "models?/" as a directory trigger:
        # that name is also commonly used FOR ORM model definitions
        # themselves (infrastructure concern), so matching it here would
        # false-positive on the very files meant to contain these imports.
        if echo "$_lf" | grep -qiE '/(domain|entities)/'; then
            # Python: ORM, HTTP framework, and raw infra-driver imports
            _FW=$(grep -nE '^[[:space:]]*(from|import)[[:space:]]+(sqlalchemy|django\.(db|contrib)|peewee|tortoise|sqlmodel|pymongo|psycopg2|redis|boto3|requests|httpx|fastapi|flask|celery)\b' "$_lf" 2>/dev/null | grep -v '^\s*#' | head -5 || true)
            # Java/Spring: JPA/Hibernate annotations, Spring stereotypes leaking into domain
            _FW_JAVA=$(grep -nE '(javax\.persistence|jakarta\.persistence|org\.hibernate|org\.springframework\.(stereotype|web)|@Entity\b|@Table\b|@Column\b|@RestController|@Repository)' "$_lf" 2>/dev/null | grep -v '^\s*//' | head -5 || true)
            # JS/TS: common ORM/HTTP imports leaking into domain
            _FW_JS=$(grep -nE "(from ['\"](typeorm|@prisma/client|sequelize|mongoose|express|fastify)['\"])" "$_lf" 2>/dev/null | head -5 || true)
            _FW="${_FW}${_FW_JAVA}${_FW_JS}"
            if [ -n "$_FW" ]; then
                LAYER_VIOLATIONS="${LAYER_VIOLATIONS}DOMAIN_HAS_FRAMEWORK_IMPORT ${_lf}:\n${_FW}\n"
            fi
        fi
    done <<< "$CHANGED_FILES"

    if [ -n "$LAYER_VIOLATIONS" ]; then
        echo -e "${RED}COVENANT BLOCK: Layer boundary violation(s) detected in changed files:${RESET}" >&2
        echo -e "$LAYER_VIOLATIONS" | head -40 >&2
        echo "SQL belongs in repositories/ only. HTTP framework imports belong in routes/ only." >&2
        echo "The domain/entities layer must have zero ORM/HTTP/infrastructure imports." >&2
        echo "Move the violating code to the correct layer before committing." >&2
        OUTCOME="block:layer-boundary"
        _json_append_audit "$NOW_ISO" "$COVENANT_TRIGGER" "$TOTAL_SPENT" "$OUTCOME"
        exit 1
    fi
    echo "COVENANT: layer boundary scan clean." >&2
fi

_run_test_queue() {
    local runner_idx=0 total=${#TEST_RUNNERS[@]}
    local TIMEOUT_SEC TEST_TIMEOUT
    TIMEOUT_SEC=$(_json_get "$COVENANT_STATE" "thresholds.command_timeout_sec")
    TIMEOUT_SEC="${TIMEOUT_SEC:-30}"
    TEST_TIMEOUT=$(( TIMEOUT_SEC * 10 ))

    for runner in "${TEST_RUNNERS[@]}"; do
        runner_idx=$(( runner_idx + 1 ))
        echo "COVENANT: running test suite ${runner_idx}/${total}..." >&2
        if command -v timeout >/dev/null 2>&1; then
            if ! timeout "$TEST_TIMEOUT" bash -c "$runner" 2>&1; then
                echo -e "${RED}COVENANT BLOCK: test suite ${runner_idx}/${total} failed or timed out.${RESET}" >&2
                echo "  Command: ${runner}" >&2
                return 1
            fi
        else
            if ! bash -c "$runner"; then
                echo -e "${RED}COVENANT BLOCK: test suite ${runner_idx}/${total} failed.${RESET}" >&2
                echo "  Command: ${runner}" >&2
                return 1
            fi
        fi
    done
    return 0
}

# TESTS_RAN feeds the final "COVENANT PASS" summary line's tests= field — a
# corner-cutting engineer reading only that one final line (not the full
# scrollback) would otherwise see "COVENANT PASS: all checks clean" with no
# mechanical signal that pre-commit's tests are opt-in and were, in fact,
# never executed on this run. The "COVENANT: tests opt-in..." message above
# already says so, but it's easy to miss mid-scrollback; putting it on the
# terminal PASS line itself makes it unmissable.
TESTS_RAN="none"
if [ "$RUN_TESTS" = "true" ] && [ ${#TEST_RUNNERS[@]} -gt 0 ]; then
    TESTS_RAN="ran"
    echo "COVENANT: running ${#TEST_RUNNERS[@]} test suite(s) (coverage threshold: ${COVERAGE_THRESHOLD}%)..." >&2
    if ! _run_test_queue; then
        OUTCOME="block:tests"
        _json_append_audit "$NOW_ISO" "$COVENANT_TRIGGER" "$TOTAL_SPENT" "$OUTCOME"
        exit 1
    fi

    # ── COVERAGE COVENANT ─────────────────────────────────────────────────────────
    # Executes COVERAGE_CMD (set by init), parses the trailing percentage, and
    # blocks when line coverage drops below COVERAGE_THRESHOLD. Lowering the
    # threshold requires a human PR (covenant_state.json is agent-immutable).
    if [ -n "$COVERAGE_CMD" ]; then
        echo "COVENANT: measuring coverage (min ${COVERAGE_THRESHOLD}%)..." >&2
        COV_OUTPUT=$(_run_with_timeout "coverage" bash -c "$COVERAGE_CMD" 2>&1 || true)
        COV_PCT=$(echo "$COV_OUTPUT" | grep -oE '[0-9]+(\.[0-9]+)?%' | tail -1 | tr -d '%')
        if [ -z "$COV_PCT" ]; then
            echo -e "${YELLOW}⚠ COVERAGE: could not parse a percentage from COVERAGE_CMD output. Recording NO_COVERAGE.${RESET}" >&2
            _json_append_audit "$NOW_ISO" "$COVENANT_TRIGGER" "$TOTAL_SPENT" "warn:no_coverage_parse"
        else
            # Integer-truncate for a dependency-free comparison (e.g. 79.9 -> 79).
            COV_INT=${COV_PCT%.*}
            if [ "${COV_INT:-0}" -lt "$COVERAGE_THRESHOLD" ] 2>/dev/null; then
                echo -e "${RED}COVENANT BLOCK: coverage ${COV_PCT}% < ${COVERAGE_THRESHOLD}% threshold.${RESET}" >&2
                OUTCOME="block:coverage"
                _json_append_audit "$NOW_ISO" "$COVENANT_TRIGGER" "$TOTAL_SPENT" "$OUTCOME"
                exit 1
            fi
            echo -e "${GREEN}COVENANT: coverage ${COV_PCT}% ≥ ${COVERAGE_THRESHOLD}%.${RESET}" >&2
        fi
    else
        echo "COVENANT: no COVERAGE_CMD configured — recording NO_COVERAGE (set it at init to enforce the coverage threshold)." >&2
        _json_append_audit "$NOW_ISO" "$COVENANT_TRIGGER" "$TOTAL_SPENT" "warn:no_coverage_cmd"
    fi
elif [ "$RUN_TESTS" != "true" ] && [ ${#TEST_RUNNERS[@]} -gt 0 ]; then
    TESTS_RAN="skipped"
    echo "COVENANT: tests opt-in at pre-commit (--run-tests=false). Mandatory at pre-push and on CORE_FILES changes." >&2
    echo "COVENANT: queued runners (not executed): ${TEST_RUNNERS[*]}" >&2
fi

if $HAS_BACKEND && [ -n "$COMPLEXITY_CMD" ]; then
    echo "COVENANT: running complexity check (threshold: cc <= ${COMPLEXITY_THRESHOLD})..." >&2
    COMPLEXITY_OUTPUT=$(_run_with_timeout "complexity" bash -c "$COMPLEXITY_CMD" 2>&1 || true)
    if [ -n "$COMPLEXITY_OUTPUT" ]; then
        echo -e "${RED}COVENANT BLOCK: complexity exceeds threshold (cc > ${COMPLEXITY_THRESHOLD}):\n${COMPLEXITY_OUTPUT}${RESET}" >&2
        OUTCOME="block:complexity"
        _json_append_audit "$NOW_ISO" "$COVENANT_TRIGGER" "$TOTAL_SPENT" "$OUTCOME"
        exit 1
    fi
fi

# ── STEP 7: FRONTEND CHECKS (lint/type only — tests run via TEST_RUNNERS queue) ─
if $HAS_FRONTEND && [ -n "$FRONTEND_LINT_CMD" ]; then
    echo "COVENANT: running frontend lint..." >&2
    if ! _run_with_timeout "frontend-lint" bash -c "$FRONTEND_LINT_CMD"; then
        echo -e "${RED}COVENANT BLOCK: frontend lint failed.${RESET}" >&2
        OUTCOME="block:frontend-lint"
        _json_append_audit "$NOW_ISO" "$COVENANT_TRIGGER" "$TOTAL_SPENT" "$OUTCOME"
        exit 1
    fi
fi

if $HAS_FRONTEND && [ -n "$FRONTEND_TYPE_CMD" ]; then
    echo "COVENANT: running frontend type check..." >&2
    if ! _run_with_timeout "frontend-type" bash -c "$FRONTEND_TYPE_CMD"; then
        echo -e "${RED}COVENANT BLOCK: frontend type check failed.${RESET}" >&2
        OUTCOME="block:frontend-type"
        _json_append_audit "$NOW_ISO" "$COVENANT_TRIGGER" "$TOTAL_SPENT" "$OUTCOME"
        exit 1
    fi
fi

# ── STEP 8: ALL CHECKS PASSED — write receipt + advance ledger ────────────────
# CRITICAL: last_pass_sha is written ONLY here, after all checks exit 0.
# Never write it on entry or on cold-start — a mid-run block would poison the ledger.
# Keyed by branch (_BRANCH_KEY) to prevent cross-branch diff contamination.
if [ -f "$COVENANT_STATE" ]; then
    _json_set "$COVENANT_STATE" "last_pass_sha.${_BRANCH_KEY}" "\"${HEAD_SHA}\""
    _json_set "$COVENANT_STATE" "last_pass_timestamp" "\"${NOW_ISO}\""
    _json_set "$COVENANT_STATE" "token.token_spent_today" "$TOTAL_SPENT"
    # Clear session spend tmp after accumulating
    rm -f "$SESSION_SPEND"
fi

# Write the fingerprint receipt keyed by COMMIT_TREE_FP so pre-push can verify
# this exact tree was verified. Pre-commit writes the index tree; a no-receipt
# pre-push that reaches here writes its own (HEAD tree) receipt.
if [ -n "$COMMIT_TREE_FP" ]; then
    _receipt_write "$COMMIT_TREE_FP" "$CURRENT_BRANCH"
    echo -e "${GREEN}COVENANT: receipt written for tree ${COMMIT_TREE_FP:0:12}.${RESET}" >&2
fi

# Watchdog runs at pre-push only — the natural checkpoint before Claude Code
# next queries the graph, and cheap enough not to add per-commit overhead.
# _ensure_graph_freshness (below) already self-heals the crash case whenever
# THIS run's changed files trigger a rebuild anyway; the watchdog covers the
# gap where they don't.
if [ "$COVENANT_TRIGGER" = "pre-push" ]; then
    _ensure_graph_alive
fi
_ensure_graph_freshness

_json_append_audit "$NOW_ISO" "$COVENANT_TRIGGER" "$TOTAL_SPENT" "pass"

# "spend" rather than the more obvious field label here — this line is
# itself part of covenant.sh, committed as .githooks/covenant.sh on every
# fresh install, and STEP 5's secrets scan requires that other word to be
# glued directly to a colon or equals sign to count as a match; using it as
# this label used to satisfy exactly that on every single fresh install's own
# governance commit, even with no injected secret anywhere. Confirmed by
# direct reproduction, not a hypothetical — see the dedicated regression test
# in tests/covenant/secrets_block.bats.
echo -e "${GREEN}COVENANT PASS: all checks clean | branch=${CURRENT_BRANCH} | mode=${SCAN_MODE} | tier3=${CORE_FILES_TOUCHED} | tests=${TESTS_RAN} | spend=${TOTAL_SPENT}/${TOKEN_BUDGET}${RESET}" >&2
exit 0
